// Tracks one-way right swipes privately, creates a match only when both sides
// have swiped right on each other, and permanently excludes judged profiles
// (either direction) from a user's future deck.
class DatingService {
    private final Map<String, Set<String>> rightSwipesBySwiper = new HashMap<>(); // swiperId -> who they liked
    private final Map<String, Set<String>> everJudgedBySwiper = new HashMap<>();      // swiperId -> everyone they've swiped on, either direction
    private final Set<String> matchedPairKeys = new HashSet<>();                          // canonical "a|b" keys, a < b alphabetically

    // Returns "MATCH" if this reciprocates an existing right swipe from the
    // target, or "LIKED_NO_MATCH_YET" if the target has not swiped right on
    // this user yet.
    String swipeRight(String swiperId, String targetId) {
        everJudgedBySwiper.computeIfAbsent(swiperId, id -> new HashSet<>()).add(targetId);
        rightSwipesBySwiper.computeIfAbsent(swiperId, id -> new HashSet<>()).add(targetId);

        boolean targetAlreadyLikedSwiper = rightSwipesBySwiper
            .getOrDefault(targetId, Collections.emptySet())
            .contains(swiperId);

        if (targetAlreadyLikedSwiper) {
            matchedPairKeys.add(canonicalPairKey(swiperId, targetId)); // exactly one record, regardless of who swiped last
            return "MATCH";
        }
        return "LIKED_NO_MATCH_YET"; // never visible to the target until they swipe right too
    }

    void swipeLeft(String swiperId, String targetId) {
        everJudgedBySwiper.computeIfAbsent(swiperId, id -> new HashSet<>()).add(targetId); // still permanently excluded going forward
    }

    int matchCount() {
        return matchedPairKeys.size();
    }

    // Filters out any candidate this user has already judged, in either direction, ever.
    List<String> buildDeck(String userId, List<String> candidates) {
        Set<String> judged = everJudgedBySwiper.getOrDefault(userId, Collections.emptySet());
        List<String> deck = new ArrayList<>();
        for (String candidate : candidates) {
            if (!judged.contains(candidate)) deck.add(candidate);
        }
        return deck;
    }

    private String canonicalPairKey(String a, String b) {
        return (a.compareTo(b) < 0) ? (a + "|" + b) : (b + "|" + a); // order-independent, so both directions map to the same key
    }
}

