#include <iostream>
#include <map>
#include <set>
#include <vector>
#include <string>
using namespace std;

// Tracks one-way right swipes privately, creates a match only when both
// sides have swiped right on each other, and permanently excludes judged
// profiles (either direction) from a user's future deck.
class DatingService {
public:
    string swipeRight(const string& swiperId, const string& targetId) {
        everJudgedBySwiper[swiperId].insert(targetId);
        rightSwipesBySwiper[swiperId].insert(targetId);

        bool targetAlreadyLikedSwiper = rightSwipesBySwiper[targetId].count(swiperId) > 0;

        if (targetAlreadyLikedSwiper) {
            matchedPairKeys.insert(canonicalPairKey(swiperId, targetId)); // exactly one record, regardless of who swiped last
            return "MATCH";
        }
        return "LIKED_NO_MATCH_YET"; // never visible to the target until they swipe right too
    }

    void swipeLeft(const string& swiperId, const string& targetId) {
        everJudgedBySwiper[swiperId].insert(targetId); // still permanently excluded going forward
    }

    int matchCount() {
        return static_cast<int>(matchedPairKeys.size());
    }

    vector<string> buildDeck(const string& userId, const vector<string>& candidates) {
        const set<string>& judged = everJudgedBySwiper[userId];
        vector<string> deck;
        for (const auto& candidate : candidates) {
            if (judged.find(candidate) == judged.end()) deck.push_back(candidate);
        }
        return deck;
    }

private:
    map<string, set<string>> rightSwipesBySwiper; // swiperId -> set of who they liked
    map<string, set<string>> everJudgedBySwiper;     // swiperId -> everyone they've swiped on, either direction
    set<string> matchedPairKeys;                        // canonical "a|b" keys, a < b alphabetically

    string canonicalPairKey(const string& a, const string& b) {
        return (a < b) ? (a + "|" + b) : (b + "|" + a); // order-independent, so both directions map to the same key
    }
};

int main() {
    DatingService dating;

    // Alice swipes right on Bob. Bob has not swiped on Alice yet, so no match forms.
    cout << "Alice swipes right on Bob: " << dating.swipeRight("alice", "bob") << endl;

    // Bob swipes right on Carol. Carol has not swiped on Bob yet, so no match forms.
    cout << "Bob swipes right on Carol: " << dating.swipeRight("bob", "carol") << endl;

    // Bob swipes right on Alice. Alice already swiped right on Bob: a mutual match forms now.
    cout << "Bob swipes right on Alice: " << dating.swipeRight("bob", "alice") << endl;

    // Carol swipes right on Bob. Bob already swiped right on Carol: a mutual match forms now too.
    cout << "Carol swipes right on Bob: " << dating.swipeRight("carol", "bob") << endl;

    cout << "Total matches created: " << dating.matchCount() << endl;

    // Alice's deck should now exclude Bob, since she already swiped on him.
    vector<string> aliceCandidates = {"bob", "dave", "erin"};
    vector<string> deck = dating.buildDeck("alice", aliceCandidates);
    cout << "Alice's deck, excluding already-judged profiles: ";
    for (const auto& c : deck) cout << c << " ";
    cout << endl;

    return 0;
}

